<?php require 'config.php';require 'functions.php';require_login();$s=$pdo->prepare("SELECT * FROM orders WHERE user_id=? ORDER BY created_at DESC");$s->execute([$_SESSION['user']['id']]);$orders=$s->fetchAll();$pageTitle='My account — Shopease';require 'header.php';?>
<section class="page-wrap"><p class="eyebrow">YOUR ACCOUNT</p><h1 class="page-title">Hello, <?= e($_SESSION['user']['name']) ?></h1><h2>Order history</h2><?php if(!$orders): ?><p class="muted">You have not placed an order yet.</p><?php else: ?><div class="table-wrap"><table><tr><th>Order</th><th>Date</th><th>Total</th><th>Status</th></tr><?php foreach($orders as $o): ?><tr><td>#<?= $o['id'] ?></td><td><?= e($o['created_at']) ?></td><td><?= money($o['total']) ?></td><td><?= e($o['status']) ?></td></tr><?php endforeach; ?></table></div><?php endif; ?></section><?php require 'footer.php'; ?>
